 function drawGrass(ctx,d,time=performance.now()/1000){const t=time,wind=Math.sin(t*1.9-d.x*.007+d.y*.003)*.11+Math.sin(t*.43)*.04;ctx.save();ctx.translate(Math.round(d.x/2)*2,Math.round(d.y/2)*2);ctx.transform(1,0,wind,1,0,0);if(d.kind==='grass')AI.Art?.draw(ctx,'tuftlow_1',0,0,{scale:1});else snowArt(ctx,'tuftlow_1',0,0,d.s>.7?1:.85);ctx.restore();}
