 function tentSprite(index){if(tentSprites.has(index))return tentSprites.get(index);if(!tentAtlasImage.complete||!tentAtlasImage.naturalWidth)return null;const c=document.createElement('canvas');c.width=128;c.height=126;const g=c.getContext('2d');g.drawImage(tentAtlasImage,index?144:16,17,128,126,0,0,128,126);const im=g.getImageData(0,0,128,126),d=im.data,bg=[d[0],d[1],d[2]],seen=new Uint8Array(128*126),todo=[];for(let x=0;x<128;x++)todo.push(x,125*128+x);for(let y=0;y<126;y++)todo.push(y*128,y*128+127);while(todo.length){const n=todo.pop();if(n<0||n>=seen.length||seen[n])continue;seen[n]=1;const k=n*4;if(d[k+3]>0&&Math.max(...bg.map((v,j)=>Math.abs(v-d[k+j])))>14)continue;d[k+3]=0;const x=n%128;if(x)todo.push(n-1);if(x<127)todo.push(n+1);todo.push(n-128,n+128);}let x0=128,y0=126,x1=0,y1=0;for(let y=0;y<126;y++)for(let x=0;x<128;x++){if(d[(y*128+x)*4+3]<100)continue;x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}g.putImageData(im,0,0);const out=document.createElement('canvas');out.height=52;out.width=Math.round((x1-x0+1)/(y1-y0+1)*52);const q=out.getContext('2d');q.imageSmoothingEnabled=false;q.drawImage(c,x0,y0,x1-x0+1,y1-y0+1,0,0,out.width,out.height);tentSprites.set(index,out);return out;}
