   for(let yy=0;yy<cv.height;yy++)for(let xx=0;xx<W;xx++){const k=(yy*W+xx)*4;if(original[k+3]<128)continue;let exposed=false;for(let dy=1;dy<=3;dy++)if(yy-dy<0||original[((yy-dy)*W+xx)*4+3]<128)exposed=true;if((exposed||name.startsWith('tuftlow')||original[k+1]>original[k]*1.08&&yy<cv.height*.76)&&yy<cv.height*.92){const shade=hash(xx,yy,51);im.data[k]=207+shade*32;im.data[k+1]=226+shade*23;im.data[k+2]=237+shade*18;}}
