 let regiRun=null,regiPlayer=null;const ownsRegis=()=>regigigasEligible(R.DB?.save?.owned);
 function regigigasState(){return {phase:regiRun?.seed===seed?regiRun.phase:'dormant',eligible:ownsRegis(),missing:missingRegis(R.DB?.save?.owned),age:regiRun?.age||0,dex:regiRun?.entity?.dex||null};}
