 function spawnRegigigas(){if(!ownsRegis()||!active()||zone!=='regigigas'||!regiRun||regiRun.phase==='defeated')return null;if(regiRun.entity&&!regiRun.entity.dead)return regiRun.entity;const d=R.DEX_BY[486];if(!d||!R.SPRITE_META[486])return null;const t=Number(R.Game.time)||0,T=[...(R.Enemies.BOSSES||[])].sort((a,b)=>Math.abs((a.at||0)-t)-Math.abs((b.at||0)-t))[0]||{},sc=R.Enemies.scale?.(t)||{hp:1,dmg:1,spd:1};model.setRegigigasReleased(true);const def={dex:486,name:d.name,hp:Math.max(1600,(T.hp||1000)*2),spd:42,dmg:Math.max(12,T.dmg||15),xp:Math.max(200,(T.xp||100)*3),behavior:'charger',shotCd:2,shotDmg:Math.max(8,T.shotDmg||10),range:230};const e=new R.Enemy(def,0,-100,sc,true);e.legend=true;e.__templeGuardian=true;e.__regigigasGuardian=true;const admitted=R.EnemyMgr.add(e);if(admitted===false){model.setRegigigasReleased(false);return null;}regiRun.entity=e;regiRun.phase='awake';e.psxK=Math.max(2.5,e.psxK||1);e._psxKOn=true;if(e.psx){e.psx.stance='hostile';AI.Combat.engage(e,e.psx,R.Game.player,'regigigas-awakening');}R.FX.burst(0,-110,'#a39b86',42,150);R.Spawner.say('Regigigas has awakened! Defeat it to befriend it.',4);return e;}
 function updateRegigigas(dt){if(regiRun?.seed!==seed||regiPlayer!==R.Game.player)resetRegiRun();if(zone!=='regigigas')return;const p=R.Game.player;if(regiRun.phase==='defeated')return;if(regiRun.entity){if(regiRun.entity.dead&&regiRun.entity.hp<=0){regiRun.phase='defeated';if(ownsRegis()&&!regiRun.rewarded){regiRun.rewarded=true;R.DB.grant(486);R.DB.commit();R.UI.toast('Regigigas joined you!',4000);}}return;}if(regiRun.phase==='awake'){spawnRegigigas();return;}if(regiRun.phase==='cracking'){regiRun.age+=Math.min(.2,Math.max(0,dt));if(regiRun.age>=4.2){if(ownsRegis())spawnRegigigas();else{regiRun.phase='dormant';regiRun.age=0;}}return;}if(!p||Math.abs(p.x)>140||p.y< -50||p.y>130)return;if(!ownsRegis()){if(!regiRun.notified){regiRun.notified=true;R.Spawner.say('Three ancient powers are needed: Regirock, Regice and Registeel.',4);}return;}regiRun.phase='cracking';regiRun.age=0;R.Sprites.preload?.([486],4500);R.Spawner.say('The three Regis resonate. The ancient stone begins to crack...',4);}
